    private enum CodingKeys: String, CodingKey {
        case studentId = "stuId"
        case planId = "pianoId"
        case matId = "matId"
        case schemaId = "schemaId"
        case choicePlanId = "scePianoId"
        case choiceId = "sceltaId"
        case orderNumber = "ordNum"
