        self.courseYear = container.decodeLenient(Int.self, forKey: .courseYear)
        self.anticipatedCourseYear = container.decodeLenient(Int.self, forKey: .anticipatedCourseYear)
        self.choiceType = container.decodeLenient(Esse3ChoiceType2.self, forKey: .choiceType)
