        self.teachingUnitType = container.decodeLenient(Esse3TeachingUnitType.self, forKey: .teachingUnitType)
        self.minTeachingUnit = container.decodeLenient(Float.self, forKey: .minTeachingUnit)
        self.maxTeachingUnit = container.decodeLenient(Float.self, forKey: .maxTeachingUnit)
        self.tafMode = container.decodeLenient(Esse3TafMode.self, forKey: .tafMode)
        self.optionalFlag = container.decodeLenient(Int.self, forKey: .optionalFlag)
        self.treasureFlag = container.decodeLenient(Int.self, forKey: .treasureFlag)
        self.overrideFlag = container.decodeLenient(Int.self, forKey: .overrideFlag)
        self.resetCreditsFlag = container.decodeLenient(Int.self, forKey: .resetCreditsFlag)
        self.authorizationFlag = container.decodeLenient(Int.self, forKey: .authorizationFlag)
        self.systemRuleFlag = container.decodeLenient(Int.self, forKey: .systemRuleFlag)
        self.externalCode = container.decodeLenient(String.self, forKey: .externalCode)
    }

